window.products.push({"id":259142,"name":"Epic Graffiti 'White Doodle on Bike Christmas' by Ryan Fowler, Canvas Wall Art, 37\"x37\",Green","category":"homeandappliances","retail price":179.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81UOtbdTlxL._AC_SL1500_.jpg","description":"\"White Doodle on Bike Christmas\" by Ryan Fowler\\n\\nRyan Fowler studied photography and photographic printing methods, both in a darkroom and on a computer. He uses his drawings, paintings, and graphic illustrations to create his work inspired by nature, advertising design, and New England and Pacific Northwest iconography. Ryan uses a combination of traditional and modern techniques for his various subject matters; which include animals, landscapes, children's art, typography, and graphic design. Dimensions: 37\"W x 1.5\"L x 37\"H","images":["https://m.media-amazon.com/images/I/81UOtbdTlxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Epic Graffiti","source_asin":"B07L8P3V3S","category_path":"Home & Kitchen"},"sku":"BM-259142","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07L8P3V3S","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07L8P3V3S","price_pending":true,"merchant_ready":false});
